import json, math, collections, statistics, hashlib
from pathlib import Path
import numpy as np
from pymatgen.core import Structure
from rhombus.transport.cohort_evidence import _digest_structure
from scipy.stats import spearmanr, rankdata
base=Path('data/benchmarks/v3_static')
load=lambda f:json.loads((base/f).read_text())
comp=load('completed_dynamics_audit_v1.json'); basin=load('basin_steric_diagnostic_v1.json'); fixed=load('priority1_fixed_windows_v1.json'); full=load('same_hash_full_comparison_v1.json')
bi={r['relaxed_sha256']:r for r in basin['rows']}; fi={r['relaxed_sha256']:r for r in fixed['rows']}; fm={r['relaxed_sha256']:r for r in full['rows']}; rows=[]
for r in comp['completed_records']:
 b=bi[r['relaxed_sha256']]; f=fi[r['relaxed_sha256']]; ratio=b['radius_A']/b['channel_ev'] if b['channel_ev']>0 else None
 if ratio is None: continue
 rows.append({**r,'saddle':ratio*(b['basin']['x_vac_basin']>0),'fixed_0.3':ratio*(f['fixed_window_fractions']['0.3']>0),'fixed_0.5':ratio*(f['fixed_window_fractions']['0.5']>0),'normalized_displacement':r['mean_li_displacement_A']/math.sqrt(r['production_steps'])})
def metrics(rows,key,target='mean_li_displacement_A',threshold=.8):
 x=[r[key] for r in rows]; y=[r[target] for r in rows]; labels=[v>=threshold for v in y]; n1=sum(labels); n0=len(y)-n1
 rho=float(spearmanr(x,y).statistic) if len(set(x))>1 and len(set(y))>1 else None
 auc=float((sum(v for v,l in zip(rankdata(x),labels) if l)-n1*(n1+1)/2)/(n1*n0)) if n1 and n0 else None
 return {'n':len(rows),'formula_count':len(set(r['formula'] for r in rows)),'positive':n1,'rho':rho,'auc':auc}
scores=('saddle','fixed_0.3','fixed_0.5'); summary={}
for n in (1000,3000,8000):summary[str(n)]={k:metrics([r for r in rows if r['production_steps']==n],k) for k in scores}
summary['all_sqrt_steps']={k:metrics(rows,k,'normalized_displacement',.8/math.sqrt(1000)) for k in scores}
groups=collections.defaultdict(list)
for r in rows:groups[r['formula']].append(r)
formula=[{'formula':f,**{k:statistics.mean(r[k] for r in rs) for k in (*scores,'mean_li_displacement_A','normalized_displacement')},'run_count':len(rs),'step_counts':sorted({r['production_steps'] for r in rs})} for f,rs in sorted(groups.items())]
rng=np.random.default_rng(20261029); draws=rng.integers(0,len(formula),(1000,len(formula)))
summary['formulas']={}
for k in scores:
 m=metrics(formula,k); bs=[metrics([formula[i] for i in d],k) for d in draws]
 for metric in ('rho','auc'):
  vals=[x[metric] for x in bs if x[metric] is not None and math.isfinite(x[metric])];m[metric+'_ci95']=np.quantile(vals,[.025,.975]).tolist() if vals else None;m[metric+'_valid_bootstrap']=len(vals)
 summary['formulas'][k]=m
host=[]
for s in comp['structures']:
 if s['subset'] not in ('COMPLETED','EXPLOSIVE'): continue
 entry=fm[s['relaxed_sha256']]; raw=json.loads(Path(entry['p1_path']).read_text()); assert _digest_structure(raw['result']['relaxed_structure_dict']) == s['relaxed_sha256']; structure=Structure.from_dict(raw['result']['relaxed_structure_dict']); ids=[i for i,site in enumerate(structure) if site.specie.symbol!='Li']; dist=structure.distance_matrix[np.ix_(ids,ids)].copy();np.fill_diagonal(dist,np.inf);i,j=np.unravel_index(np.argmin(dist),dist.shape); pair='-'.join(sorted((structure[ids[i]].specie.symbol,structure[ids[j]].specie.symbol))); counts=structure.composition.get_el_amt_dict(); host.append({'subset':s['subset'],'batch_id':s['batch_id'],'formula':s['formula'],'relaxed_sha256':s['relaxed_sha256'],'volume_per_atom_A3':structure.volume/len(structure),'min_distance_A':float(dist[i,j]),'closest_pair':pair,'anion_counts':{a:counts.get(a,0) for a in ('O','S','Se','F','Cl','Br','I')},'atom_count':len(structure),'p1_path':entry['p1_path'],'p1_file_sha256':hashlib.sha256(Path(entry['p1_path']).read_bytes()).hexdigest()})
out={'schema':'priority2-statistics-v1','source_commit':'1ea4a5c2ffaaf019c246688c0b7106e3e16bcec0','inputs_sha256':{str(base/f):hashlib.sha256((base/f).read_bytes()).hexdigest() for f in ('completed_dynamics_audit_v1.json','basin_steric_diagnostic_v1.json','priority1_fixed_windows_v1.json','same_hash_full_comparison_v1.json')},'driver_source':Path('/tmp/priority2.py').read_text(),'metrics':summary,'formula_rows':formula,'run_rows':rows,'host_rows':host,'scope':'EXPLORATORY_RETROSPECTIVE_NO_CAUSAL_OR_PROSPECTIVE_VALIDATION','qualification':'ABSTAIN'}
(base/'priority2_statistics_v1.json').write_text(json.dumps(out,sort_keys=True,indent=2,allow_nan=False)+'\n');print(json.dumps(summary,indent=2));print('host count',len(host), collections.Counter(x['subset'] for x in host))
